          "conditionChangingAssessment": "Nếu chênh lệch tỷ giá thị trường tự do nới rộng trên 1,5% so với giá mua can thiệp, áp lực bảo vệ tỷ giá và kiểm soát cung tiền sẽ gia tăng.",
