      "pageTitle": "Hàng Việt lên sàn ngoại dễ hay khó?",
      "headline": "Hàng Việt lên sàn ngoại dễ hay khó?",
      "summary": "Thương mại điện tử xuyên biên giới giúp doanh nghiệp Việt tiếp cận người mua toàn cầu dễ hơn. Nhưng từ mở gian hàng đến bán được, có lãi và đứng vững lại là hành trình đầy thách thức.",
